insert into ability_seed (rules_version, id, name, description, effect) values
    ('3.0', 'adaptability', 'Adaptability', 'The Pokemon will easily adapt to its surroundings, it will travel with ease, no matter the terrain.', 'Whenever this Pokemon uses a Physical or Special Move that matches their Type, add 1 Extra die to the Damage pool of that Move.'),
    ('3.0', 'aerilate', 'Aerilate', 'The Pokemon never touches the ground, a neverending wind current can be felt swirling around it.', 'Normal-Type Moves that the Pokemon uses will deal damage as if they were Flying-Type, affecting STAB, weakness and resistance. Add 1 Extra die to the Damage Pool of Flying moves.'),
    ('3.0', 'aftermath', 'Aftermath', 'When hurt or upset, the Pokemon will prepare to burst. If hit hard enough, it will explode on contact. They also tend to hold grudges.', 'If this Pokemon faints due to a Non-Ranged Physical Move, the User of that attack is dealt 2 Damage.'),
    ('3.0', 'air-lock', 'Air Lock', 'The Pokemon surrounds itself in a vacuum. Every particle of rain, sand, and hail stands floating still around it, and even heat is filtered out of the place.', 'Negate all the effects of a Weather in the field. If no weather is active, they cannot be activated by Moves or Abilities. If one is already active, it does not disappear but provides no effects. Unique Ability.'),
    ('3.0', 'analytic', 'Analytic', 'The Pokemon will never charge recklessly, it will take a moment to think about the best decision to make in any situation.', 'If this Pokemon has a lower initiative than its target, Add 1 Extra die to all of their Damage Pools.'),
    ('3.0', 'anger-point', 'Anger Point', 'The Pokemon will easily get aggressive. Little to no provocation is needed for it to start throwing a tantrum and ripping everything to shreds.', 'If a foe lands a Critical Hit on this Pokemon, increase this Pokemon''s Strength Attribute by 3.'),
    ('3.0', 'anger-shell', 'Anger Shell', 'The Pokemon gets frustrated if things are not going their way, they are prone to break their own shell in their rage.', 'When this Pokemon''s HP is half or less, increase its Strength, Special, and Dexterity Attributes by 1 but Reduce its Defense and Sp. Defense by 1.'),
    ('3.0', 'anticipation', 'Anticipation', 'The Pokemon is always alert for threats and rarely sits to relax. If it perceives a potential danger it will get anxious and start shuddering.', 'If any foe knows a Move that would deal Lethal or Super Effective damage against this Pokemon, it will alert its Trainer.'),
    ('3.0', 'arena-trap', 'Arena Trap', 'The ground around this Pokemon becomes really soft and hard to walk in. When in danger, it will sink the ground around itself creating a shifting sand pit.', 'Pokemon entering or already on the foe''s side of the field become blocked as long as this Pokemon is on the field. Pokemon with immunity to Ground-Type Moves are not affected.'),
    ('3.0', 'armor-tail', 'Armor Tail', 'The Pokemon uses its tail as armor. Almost like it had eyes on its back, always alert against surprise attacks.', 'The User and allies in range can''t be the target of Physical or Special Moves with the Reaction Added Effect.'),
    ('3.0', 'aroma-veil', 'Aroma Veil', 'This Pokemon lets off a nice smell that helps you to stay relaxed and focused even under stressful situations', 'User and Allies in Range are immune to the "Love" Status Condition and the effects of the moves: Taunt, Torment, Spite, Attract, Disable, Encore, and Heal Block.'),
    ('3.0', 'as-one', 'As One', 'Two Pokemon join forces, one riding on the other''s back. Together, they ride for ruin and the world''s ending.', 'This ability trigger a form change that combines the attributes and movepool of two Allied Pokemon. Choose one ability from each of the two Pokemon forming this union, the joint form of these Pokemon may use those two Abilities at the same time. Unique Ability.'),
    ('3.0', 'aura-break', 'Aura Break', 'Anyone emitting a particularly evil aura will be purified, anyone with an aura of purity will be corrupted by evil, just for coming close to this Pokemon.', 'Invert the effects that the Abilities Dark Aura and Fairy Aura have on their users. If said Abilities would increase a Dice Pool for their User, reduce it instead. Unique Ability.'),
    ('3.0', 'bad-dreams', 'Bad Dreams', 'This Pokemon can transfer its evil intent through the world of dreams, wreaking havoc and bringing fear into the minds of those deep in slumber', 'At the end of the Round, deal 1 Damage to anyone in the battlefield that has the Sleep Status Condition. Unique Ability.'),
    ('3.0', 'ball-fetch', 'Ball Fetch', 'The Pokemon is a bit obsessed with playing "Fetch the Ball". It can play for hours and hours and never get bored of it.', 'Whenever you throw a pokeball to a wild Pokemon, if the roll for catching it is unsuccessful, the pokeball won''t break. This Pokemon will bring it back to you at the end of the Round instead. '),
    ('3.0', 'battery', 'Battery', 'This Pokemon''s presence creates an electric field that charges up electronics and even makes others feel energized.', 'Increase by 1 the Special Attribute of all Ally Pokemon in Range. Ally Pokemon get 1 Extra die to all their Special Move''s Damage pool. The User does not get these effects.'),
    ('3.0', 'battle-armor', 'Battle Armor', 'The skin of the Pokemon is covered by plates of a very resistant material, like rock, steel, or an exoskeleton.', 'If a foe lands a Critical Hit on this Pokemon, it won''t get any Bonus Dice on its Damage Dice pool for it.'),
    ('3.0', 'beads-of-ruin', 'Beads of Ruin', 'There is a cursed artifact on this Pokemon. A burning envy will corrupt the souls of anyone close. This Pokemon loves to create discord amongst others.', 'Reduce by 2 the Special Defense of everyone in the field, except this Pokemon. This Pokemon is immune to the effects of the Abilities: Beads of Ruin, Sword of Ruin, Tablets of Ruin, and Vessel of Ruin. Unique Ability.'),
    ('3.0', 'beast-boost', 'Beast Boost', 'A wicked satisfaction grows as this creature brings out destruction, for it becomes more savage with every foe that falls to its power.', 'If a foe faints because of an attack dealt by this Ultra-Beast, Increase by 1 their highest Attribute. Up to 3 points can be increased this way. Unique Ability.'),
    ('3.0', 'berserk', 'Berserk', 'This Pokemon is usually calm in demeanor, but when its life or someone it cares for is in danger, the adrenaline rush will transform it into an enraged beast.', 'When this Pokemon''s HP is half or less, Increase its Special Attribute by 2.'),
    ('3.0', 'big-pecks', 'Big Pecks', 'This tenacious Pokemon uses its beak to cover its weak spots.', 'This Pokemon cannot have its Defense reduced.'),
    ('3.0', 'blaze', 'Blaze', 'The inner and outer fire on this Pokemon''s body will burn incredibly fierce just before fading.', 'Pain Penalization won''t reduce successes from Accuracy or Damage rolls of Fire-Type Moves used by this Pokemon. Fire-Type Moves get 2 Extra dice to their Damage Pool when this Pokemon is at half HP or less.'),
    ('3.0', 'bulletproof', 'Bulletproof', 'The armor on this Pokemon''s body protects it from projectiles and small explosions.', 'Reduce by 1 all damage from Ranged Physical Moves dealt to this Pokemon. Reduce by 1 all damage from Special Moves with the words: Ball, Blast, Bomb, Cannon, Octazooka, Puff, Shot, Sphere, and Wrecker on their name.'),
    ('3.0', 'cheek-pouch', 'Cheek Pouch', 'The Pokemon is able to store food and objects inside its stretchy cheeks for later consumption. Often looking adorable while doing so.', 'This Pokemon restores 2 HP whenever it eats a berry with no HP healing effect. (e.g. Pecha Berry, Lum Berry)'),
    ('3.0', 'chilling-neigh', 'Chilling Neigh', 'This Pokemon emits a chilling and furious neigh. In ancient times of war, hearing it made the opposing armies tremble in fear.', 'If a foe faints because of a Physical or Special Move dealt by this Pokemon, Increase its Strength Attribute by 1. Up to 3 points can be increased this way.'),
    ('3.0', 'chlorophyll', 'Chlorophyll', 'The Pokemon synthesizes sunlight to get energy, if it''s kept in a sunny environment it will rarely need to eat.', 'While Sunny Weather is active, Increase this Pokemon''s Dexterity Attribute by 2.'),
    ('3.0', 'clear-body', 'Clear Body', 'The Pokemon is completely aware of all its body surroundings, trying to sneak on it will be incredibly difficult.', 'Other Pokemon cannot Increase or Reduce the Attributes of this Pokemon. This Pokemon can still Increase or Reduce its own Attributes.'),
    ('3.0', 'cloud-nine', 'Cloud Nine', 'This Pokemon will easily feel pleased, and it''s prone to be happier than others. No matter if it''s sunny or rainy it will never feel gloomy.', 'Negate the effects of Weather Conditions on this Pokemon.'),
    ('3.0', 'color-change', 'Color Change', 'This Pokemon can change its color and energy to camouflage and merge with the surroundings.', 'When this Pokemon is dealt damage it will temporarily change its type to match the type of the move that just hit it. The effect ends if the Pokemon is removed from battle.'),
    ('3.0', 'comatose', 'Comatose', 'For some reason this Pokemon is always asleep and can''t wake up. Still, it is able to understand commands and move just as if it were sleepwalking', 'The Pokemon permanently has the “Sleep” Status Ailment but it is immune to its effects. This Pokemon can''t be inflicted other Status Ailment or Condition. Moves and Abilities affecting Asleep Pokemon still have an effect on it.'),
    ('3.0', 'commander', 'Commander', 'The Pokemon has a strategic mind, even if its body is frail it can device clever plans and tell its Dodonzo friend exactly what to do.', 'If there is an Allied Dodonzo on the field, increase its Attributes and Defenses by 2. Dodonzo is blocked for the rest of the scene. All damage that would be dealt to this Pokemon is dealt to Dodonzo instead. Unique Ability.'),
    ('3.0', 'competitive', 'Competitive', 'This Pokemon''s determination grows in the face of adversity. It is always trying to compete with those around it.', 'The first time this Pokemon gets an Attribute reduced by a foe during a battle, Increase its Special by 2. '),
    ('3.0', 'compound-eyes', 'Compound Eyes', 'This Pokemon has peripheral vision that allows it to locate its targets with great precision.', 'This Pokemon gets 2 Extra Dice on the Accuracy Pool of any move with Low Accuracy. '),
    ('3.0', 'contrary', 'Contrary', 'Most of the time this pokemon will want to do the opposite of what you want. Sometimes it even contradicts itself.', 'If anything would reduce an Attribute of this Pokemon, increase it instead. If anything would increase an Attribute of this Pokemon, reduce it instead.'),
    ('3.0', 'corrosion', 'Corrosion', 'This Pokemon''s venom can eat through metal, wood, and most inorganic and organic materials. Be careful not to touch it.', 'Ignore any immunity the foe has to Poison-Type Damage and/or to be inflicted Poison and Badly Poisoned Status Ailments.'),
    ('3.0', 'costar', 'Costar', 'This Pokemon is a true pal, friend, and wingman. It will follow you on any crazy plan you concoct. The player-2 of your dynamic duo.', 'If there''s an Ally with increased Attributes/Traits as this Pokemon enters the field, copy all of the Increases onto this Pokemon. If more than one Ally has increased Attributes/Traits, choose one to copy from.'),
    ('3.0', 'cotton-down', 'Cotton Down', 'The cotton fluff on this pokemon''s body is constantly being shed, it can be used to make beautiful clothes but it''s also bothersome to walk on.', 'If Pokemon is hit with a Non-Ranged Physical Move, reduce the speed of all Pokemon in an Area close to it.'),
    ('3.0', 'cud-chew', 'Cud Chew', 'This Pokemon regurgitates food back into its mouth whenever it gets hungry. A bit disgusting but the good news is that you''ll save a lot on food.', 'If this Pokemon has a Berry as a Held item or it is hit by a Berry, it will activate its effects two times during the battle. This effect does stack with the Move “Recycle”.'),
    ('3.0', 'curious-medicine', 'Curious Medicine', 'This Pokemon likes to mix disgusting substances to supposedly create medicine. The resulting potions are dubious at best, toxic at worst.', 'When this Pokemon comes into battle, remove all Attribute Increases and Reductions on all Ally Pokemon in range. Outside of battle, the Pokemon is able to create potions that may heal HP or deal damage at the storyteller''s discretion.'),
    ('3.0', 'cursed-body', 'Cursed Body', 'This Pokemon carries a curse within itself. Crossing this Pokemon is not a good idea.', 'Whenever this Pokemon is dealt damage with a Physical or Special Move, Roll 3 Chance Dice to Disable that Move. Up to 3 Moves may be disabled this way.'),
    ('3.0', 'cute-charm', 'Cute Charm', 'It may be its twinkly eyes or its rosy cheeks, but other people and Pokemon will try to win this Pokemon''s heart.', 'If this Pokemon is hit with a Non-Ranged Physical Move, roll 3 Chance Dice to make the foe fall in Love.'),
    ('3.0', 'damp', 'Damp', 'The Pokemon gathers the humidity in the air around itself. Lighting a spark or keeping a fire on, will be almost impossible close to it.', 'No one in the field will be able to use the moves: Self-Destruct, Explosion, Misty Explosion, Mind Blown, and Burn Up while this Pokemon is in the field. The Ability Aftermath does not activate if this Pokemon is in the field.'),
    ('3.0', 'dancer', 'Dancer', 'When someone begins to dance, this Pokemon dances too. It expresses its feelings and communicates through little jigs.', 'Once per Round, if a Pokemon uses a Move with the word "Dance" (i.e. Dragon Dance, Petal Dance etc.) This Pokemon gets one free action to use the same Move immediately after with the same number of successes on Accuracy; Damage must still be rolled. Rampage Moves are only used once.'),
    ('3.0', 'dark-aura', 'Dark Aura', 'A powerful black aura comes out of this Pokemon, Shrouding the field in darkness and filling everyone''s hearts with evil, selfishness and corruption.', 'Increase 2 dice to all Damage Pools of Dark-Type Moves of all Pokemon in the field. This effect does not stack with itself. Pokemon and Trainers on the field will not cooperate with each other. Unique Ability.'),
    ('3.0', 'dauntless-shield', 'Dauntless Shield', 'The valorous resolve of this Pokemon makes it impervious to physical damage through sheer will. Its presence can be unnerving.', 'Whenever this Pokemon enters battle, Increase 2 its Defense by 2. Outside of battle, this Pokemon is immune to physical damage. Unique Ability.'),
    ('3.0', 'dazzling', 'Dazzling', 'Its beautiful scales reflect light in a mirror-like manner, no one can help but to stop in their tracks when they glance at this Pokemon.', 'Foes cannot use Reaction Moves against this Pokemon. Maneuvers can still be used.'),
    ('3.0', 'defeatist', 'Defeatist', 'This Pokemon is a pessimist by nature. When things get difficult, it will be the first to give up.', 'If this Pokemon''s HP is at half or less, roll its Loyalty requiring 2 successes every action, if the roll fails Reduce by 2 its Strength and Special for that action. If the roll is successful it keeps its attributes unchanged or restore them if they were reduced in a previous action.'),
    ('3.0', 'defiant', 'Defiant', 'This Pokemon will not yield, the harder the situation gets, the higher its fighting spirit will grow. It may, however, be a bit of a rebel.', 'The first time this Pokemon has an Attribute reduced during a battle, Increase its Strength by 2.'),
    ('3.0', 'delta-stream', 'Delta Stream', 'The wind currents blow through the entire battlefield, Pokemon might be blown away if they don''t know how to fly.', 'When this Pokemon comes out, it automatically starts the effects of Strong Winds Weather. The effects end when the Pokemon leaves the battle. (In case of stalemate, The Pokemon with highest Will might keep the dominant weather) Unique Ability.'),
    ('3.0', 'desolate-land', 'Desolate Land', 'The heat is unbearable. Your skin gets red and blistered. All water evaporates, and every step of this Pokemon makes the ground become molten lava.', 'When this Pokemon comes out, it automatically starts the effects of Desolate Weather. The effects end when the Pokemon leaves the battle. (In case of stalemate, The Pokemon with highest Will might keep the dominant weather). Unique Ability.'),
    ('3.0', 'disguise', 'Disguise', 'This Pokemon wears a convincing disguise of another Pokemon. If it receives damage, the disguise breaks, making it appear as if it received a fatal injury.', 'The first time this Pokemon would receive damage due to a Physical or Special Move, reduce that damage to zero. Entry Hazards, Weather Conditions and Status Ailments do not trigger this Ability. Unique Ability.'),
    ('3.0', 'download', 'Download', 'This Pokemon is able to scan and access digital data within computers and download the info into itself. Too much data might make it feel bloated.', 'When this Pokemon comes out it will scan its foes and give information about them. It will then Increase 1 Point to either its Strength or Special Attribute at Storyteller''s discretion. Unique Ability.'),
    ('3.0', 'dragon-maw', 'Dragon Maw', 'This Pokemon''s mandibles are full of fury and fierceness. They''ll rip and tear without mercy.', 'All Physical or special Dragon-Type Moves that this Pokemons uses have 2 Extra dice on their Damage Pool. This effect does not apply to Moves with set damage.'),
    ('3.0', 'drizzle', 'Drizzle', 'The sky will keep raining in an apparent never-ending storm for as long as this Pokemon wants to.', 'When this Pokemon comes out, it automatically starts the effects of Rain Weather. The effects end when the Pokemon leaves the battle. (In case of stalemate the Pokemon with higher Will might keep the dominant weather)'),
    ('3.0', 'drought', 'Drought', 'The Sunlight will be harshly bright, and the heat will increase in the field for as long as this Pokemon wants to.', 'When this Pokemon comes out, it automatically starts the effects of Sunny Weather. The effects end when the Pokemon leaves the battle. (In case of stalemate the Pokemon with higher Will might keep the dominant weather)'),
    ('3.0', 'dry-skin', 'Dry Skin', 'The skin of this Pokemon needs special care as it is very dry and brittle, it''ll require constant hydration and protection against the sun.', 'While Sunny Weather is active, this Pokemon will receive 1 damage at the end of each round. Fire attacks will deal 1 additional Damage to this Pokemon. Water attacks may heal 1 HP to this Pokemon instead of dealing damage.'),
    ('3.0', 'early-bird', 'Early Bird', 'Pokemon with this ability are light sleepers that will easily rise from slumber. They wake up full of energy with just a couple hours of sleep.', 'The time this Pokemon would be asleep is reduced by half and it will only need to score 2 successes on its Insight roll to wake up in battle. This effect does not apply for the Move "Rest".'),
    ('3.0', 'earth-eater', 'Earth Eater', 'This Pokemon feeds on the minerals on earth, it loves mud baths and spends most of the time burrowed underneath the ground.', 'Whenever this Pokemon is hit by a Ground-Type Move, you may Heal 1 HP instead of receiving damage. Ground-type moves do not deal damage to this Pokemon.'),
    ('3.0', 'effect-spore', 'Effect Spore', 'When stressed, this Pokemon will leak spores through its body that scatter in the air causing severe allergies.', 'If hit by a Non-Ranged Physical Move, the Pokemon rolls 3 Chance Dice to Poison, Paralyze or Sleep the foe at random.'),
    ('3.0', 'electric-surge', 'Electric Surge', 'The Pokemon can surround itself with an electric field that fills the air with tension and keeps everyone on edge.', 'When this Pokemon comes out, it automatically starts the effects of the Move Electric Terrain. (In case of stalemate the Pokemon with higher Will might keep the dominant Terrain)'),
    ('3.0', 'electromorphosis', 'Electromorphosis', 'This Pokemon can transform any kind of kinetic energy into electricity. Beware to touch it as it always has some excess charge on its body.', 'If this Pokemon receives Damage from a Physical or Special Move, Add 2 Extra Dice to the Damage Dice Pool of its next Electric Move.'),
    ('3.0', 'embody-aspect', 'Embody Aspect', 'This Pokemon''s emotions are deeply affected by the masks it wears, its personality changing completely depending on which one it is using.', 'Increase by 2 an Attribute of this Pokemon depending on the mask it wears. Teal & Wellspring Mask - Dexterity / Heartflame & Cornerstone Mask - Strength. Unique Ability.'),
    ('3.0', 'emergency-exit', 'Emergency Exit', 'The Pokemon makes tactical escapes when the situation escalates out of control. You may force him to fight despite this but it won''t like it.', 'Whenever this Pokemon''s HP reaches half or less, it will switch out to its pokeball, sending an Ally to take its place. If there is no Ally, the battle may end. This Ability''s effect is not affected by Block.'),
    ('3.0', 'fairy-aura', 'Fairy Aura', 'A powerful pink glowing aura comes out of this Pokemon, covering the field in a glimmering light, filling everyone''s hearts with peace, hope, and love.', 'Increase 2 dice to all Damage Pools of Fairy-Type Moves of all Pokemon in the field. This effect does not stack. Pokemon and Trainers on the field will not attack the user of this Ability. Unique Ability.'),
    ('3.0', 'filter', 'Filter', 'This Pokemon uses an invisible energy field to filter away harmful energies and substances.', 'If a foe uses a Move that would deal Super Effective Damage to this Pokemon, reduce by 1 the total Damage from that attack.'),
    ('3.0', 'flame-body', 'Flame Body', 'This Pokemon can willingly ignite its body on fire, receiving no harm from it. Objects that come into contact with this Pokemon may catch fire.', 'When hit by a Non-Ranged Physical Move, this Pokemon rolls 3 Chance Dice to inflict 2nd degree Burn on the foe.'),
    ('3.0', 'flare-boost', 'Flare Boost', 'A Pokemon with this Ability benefits from the extreme heat produced by fire. But they might be somewhat of a pyromaniac.', 'If this Pokemon gets any degree of Burn, Increase 2 points to its Special Attribute.'),
    ('3.0', 'flash-fire', 'Flash Fire', 'This Pokemon is capable of consuming other fire sources and adding them to its own. Walking through embers, fire, lava and hell feel like a breeze to it.', 'The first time this Pokemon is hit by a Fire-Type move, add 1 Extra die to the Damage Pool of Fire-type Moves this Pokemon uses until the end of the scene. Fire-type moves do not deal damage to this Pokemon.'),
    ('3.0', 'flower-gift', 'Flower Gift', 'This Pokemon''s petals radiate full of energy when the sun shines bright. The energy irradiated makes those around feel stronger.', 'While Sunny Weather is active, Increase 2 Points to the Strength and Sp.Defense Attribute of the User and its allies in range.'),
    ('3.0', 'flower-veil', 'Flower Veil', 'This Pokemon makes flowers grow in gardens and near other Pokemon to protect them from harm.', 'User and allies in range can''t have their Attributes/Traits reduced. User and allies in range can''t have any Status Ailment inflicted on them. Previously inflicted or self-inflicted Attribute reductions and/or ailments remain.'),
    ('3.0', 'fluffy', 'Fluffy', 'This Pokemon''s fur is so fluffy you could die. So soft and snuggly that it invites you to hug it. Hand-wash only, tumble dry with no heat, do not iron.', 'Reduce by 2 the Damage dealt to this Pokemon by All Physical Moves. Increase by 2 the Damage dealt to this Pokemon by Fire-Type Moves.'),
    ('3.0', 'forecast', 'Forecast', 'This Pokemon can absorb the elements around to adapt and survive even under extreme conditions.', 'The Type of this Pokemon will change depending on the active weather. Fire-Type under Sun, Water-Type under Rain, Ice-Type under Hail/Snow and Rock-Type under Sand.'),
    ('3.0', 'forewarn', 'Forewarn', 'When this Pokemon feels bad intentions or disaster approaching, it will mentally warn its trainer. The trainer must make a roll of Insight to get the message.', 'In battle, this Pokemon will warn about the strongest move one of its foes has. Storyteller has to reveal it to the trainer of this Pokemon in secret.'),
    ('3.0', 'friend-guard', 'Friend Guard', 'The Pokemon is adorable and evokes parental instincts in others. All of its allies will seek to protect it all the time.', 'This Pokemon does not receive damage from Moves performed by allies. Added effects may still apply.'),
    ('3.0', 'frisk', 'Frisk', 'This Pokemon can see the items others may be carrying, even if they are hidden.', 'When this Pokemon enters the battlefield, Storyteller must reveal its trainer the held item of one foe.'),
    ('3.0', 'full-metal-body', 'Full Metal Body', 'This Pokemon''s body is a thick metal armor, its shiny coat cannot be muddled. Look inside of it and you may be blinded by the sun''s brightness.', 'Other Pokemon cannot Reduce the Attributes of this Pokemon. This Pokemon can still Reduce its own Attributes. Unique Ability.'),
    ('3.0', 'fur-coat', 'Fur Coat', 'This Pokemon''s fluffy exterior is cuddly, soft, hypoallergenic, and also serves as a cushion against powerful blows.', 'Reduce by 2 the Damage dealt to this Pokemon by All Physical Moves.'),
    ('3.0', 'gale-wings', 'Gale Wings', 'This Pokemon''s wings are perfectly designed to ride the roughest winds effortlessly.', 'Add the Effect "Reaction 1" to all Flying-Type Moves of this Pokemon.'),
    ('3.0', 'galvanize', 'Galvanize', 'The body of this Pokemon is surrounded by electrical currents, this makes it very energized in everything it does.', 'Normal-Type Moves that this Pokemon uses will deal damage as if they were Electric-Type, affecting STAB, weakness and resistance. Add 1 Extra Die of Damage to Electric Moves.'),
    ('3.0', 'gluttony', 'Gluttony', 'This Pokemon eats all day long, it is always carrying food and has no problem to find food sources since it''s not a picky eater. It, however, doesn''t share.', 'This Pokemon can eat any type of food, medicine or herbal medicine with no negative. This pokemon may have up to three berries as held item instead of just one. The berries must not be of the same effect.'),
    ('3.0', 'good-as-gold', 'Good As Gold', 'The Pokemon''s body is made of the most pure gold you''d ever seen. It knows its worth, so its shine is always unbesmirched.', 'Neither foes nor Allies can Target this Pokemon with Support Moves.'),
    ('3.0', 'gooey', 'Gooey', 'This Pokemon''s sticky ooze will rub into anyone that touches it. This may become quite a burden. On the bright side, it is a natural and organic glue.', 'The first time a foe hits this Pokemon with a Non-Ranged Physical Move, reduce 1 Point to their Dexterity Attribute.'),
    ('3.0', 'gorilla-tactics', 'Gorilla Tactics', 'The Pokemon''s manners leave a lot to be desired, it is brutish and uncivilized, its only approach to facing problems: "Smash it!"', 'Whenever this Pokemon comes into battle, choose a Move. This Pokemon can only perform that Move during battle, but can use it up to 5 times per round. Increase this Pokemon''s Strength by 1.'),
    ('3.0', 'grass-pelt', 'Grass Pelt', 'This Pokemon has a lush coat of grass to protect its body, even if you cut it, it will regrow in a few days.', 'If Grassy Terrain is active, Increase this Pokemon''s Defense by 2.'),
    ('3.0', 'grassy-surge', 'Grassy Surge', 'The Pokemon can surround itself with a grass field that makes it easy to relax and laze around in the sun.', 'When this Pokemon comes out, it automatically starts the effects of the Move Grassy Terrain. (In case of stalemate the Pokemon with higher Will might keep the dominant Terrain)'),
    ('3.0', 'grim-neigh', 'Grim Neigh', 'This Pokemon emits a somber and eerie neigh. In ancient times, hearing it at night was a terrible omen.', 'If a foe faints because of a Physical or Special dealt by this Pokemon, Increase its Special Attribute by 1. Up to 3 points can be increased this way.'),
    ('3.0', 'guard-dog', 'Guard Dog', 'A territorial and protective Pokemon. It won''t ever back down or run away, not even from the most intimidating foes. Very loyal but can also be a bit scary.', 'If a foe uses a Move, Ability or Item to reduce this Pokemon''s Strength Attribute, negate that effect and increase it by 2 instead. This Pokemon is immune to the effect of Switcher Moves that would remove it from battle.'),
    ('3.0', 'gulp-missile', 'Gulp Missile', 'This Pokemon is an excellent hunter, when diving into a pool of water it will always come out with prey. And it will sometimes use the prey as a weapon.', 'If this Pokemon uses the Moves Surf or Dive, it will change forms after dealing damage. "Gulping Form" at full or more than half HP remaining, "Gorging Form" at half or less HP. If the Pokemon is dealt damage by a foe while in any of these Forms, deal 2 Dice of Damage and an effect to that foe. The user returns to its regular form afterwards. Unique Ability.'),
    ('3.0', 'guts', 'Guts', 'This Pokemon dares to do everything no one else dares to, and won''t lose its determination easily, it may be a little reckless, though.', 'While affected by a Status Ailment (Burn, Frozen, Paralysis, Poison, Sleep), Increase this Pokemon''s Strength Attribute by 2.'),
    ('3.0', 'hadron-engine', 'Hadron Engine', 'This Pokemon''s body is able to accelerate particles and transform them into energy. Theory is that it''s simply bringing forward energy from another universe.', 'When this Pokemon comes out, it automatically starts the effects of the Move Electric Terrain. (In the case of a stalemate the Pokemon with higher Will might keep the dominant Terrain). While Electric Terrain is active, increase this Pokemon''s Special Attribute by 2.'),
    ('3.0', 'harvest', 'Harvest', 'This Pokemon will naturally produce edible fruits in a short period of time, if fed with berries it will start growing them too.', 'If this Pokemon uses a berry as a held item during a fight, the berry will grow back at the end of the battle.'),
    ('3.0', 'healer', 'Healer', 'The Pokemon has healing powers, and will use them without hesitation to aid others.', 'If an Ally on the battle field has a Status Ailment, at the End of the Round this Pokemon rolls 3 Chance Dice to heal it. Outside of battle it can heal Status Ailments by spending 1 Will Point.'),
    ('3.0', 'heatproof', 'Heatproof', 'This Pokemon can resist very high temperatures without trouble.', '1st and 2nd Degree Burns deal no Damage to this Pokemon. If this Pokemon is hit by a Fire-Type Move, Reduce the total damage dealt by 2.'),
    ('3.0', 'heavy-metal', 'Heavy Metal', 'The metal covering the body of the Pokemon is so thick that it can double and sometimes triple the average weight of the Pokemon.', 'Increase the Pokemon''s weight at the storyteller''s discretion. Moves with damage based on the weight get their Damage Pool modified according to the increased weight of the user.'),
    ('3.0', 'honey-gather', 'Honey Gather', 'The Pokemon produces its own honey, you can get a small barrel of high quality honey every day.', 'A small barrel of honey can be sold for up to $100. Honey attracts wild Pokemon and feeding a Pokemon with it will make it happy.'),
    ('3.0', 'hospitality', 'Hospitality', 'The Pokemon can transform the most bitter herb into a delicious medicinal tea. It will also invite its friends for a cup whenever they have the time.', 'When this Pokemon comes out, it can spend a Will Point to heal up to 3 HP from a damaged Ally. Lethal Damage is not healed with this effect. Outside of battle it can remove the bitter taste from all healing Herbs.'),
    ('3.0', 'huge-power', 'Huge Power', 'The Pokemon has an unnatural strength that goes way beyond of what its physical appearance would suggest.', 'This Pokemon has a permanent increase to its Strength Attribute. Ranks Starter, Beginner, Standard, and Advanced Increase Strength by 1. Rank Expert and higher Increase Strength by 2.'),
    ('3.0', 'hunger-switch', 'Hunger Switch', 'This Pokemon becomes really upset if it gets hungry, it will bite and act out unless you constantly give it snacks.', 'At the end of the Round, switch this Pokemon''s Form, from "Hangry" to "Full-Belly Form" or vice versa. Outside of battle, the form changes depending on its hunger. Unique Ability.'),
    ('3.0', 'hustle', 'Hustle', 'The Pokemon will perform everything in a hurry, it keeps itself busy, but it can be kind of sloppy when it rushes something out.', 'This Pokemon gets an Extra Low Accuracy 1 and adds 2 Extra Dice to the Damage pool for all its Physical Moves.'),
    ('3.0', 'hydration', 'Hydration', 'The body of the Pokemon absorbs water and uses its moisture to maintain a healthy state.', 'When Rain weather is active, this Pokemon will cure all Status Ailments and Conditions it is affected with at the end of the round.'),
    ('3.0', 'hyper-cutter', 'Hyper Cutter', 'The claws of this Pokemon are very sharp. Their edge can''t be dulled.', 'This Pokemon can''t have its Strength Attribute reduced by Moves, Abilities, or Items. This Pokemon can still Reduce its own Strength Attribute.'),
    ('3.0', 'ice-body', 'Ice Body', 'The Pokemon''s body is almost frozen, and can cool down enclosed areas in a few minutes. It feels most comfortable when temperatures are below zero.', 'If Hail/Snow Weather is active, you may restore 1 HP to this Pokemon at the end of the Round. This Pokemon is immune to damage from Hail weather.'),
    ('3.0', 'ice-face', 'Ice Face', 'This Pokemon''s face is covered by a thick block of ice that serves as a cover for its body. If it breaks it will need freezing temperatures to restore the ice block.', 'The Pokemon has 2 Extra HP when it is on "Ice Face form". If the Ice receives 2 damage, change the Pokemon''s form to "No-Ice Form". To restore "Ice Face Form" the Pokemon must be out one whole Round while Hail/Snow weather is active. Unique Ability.'),
    ('3.0', 'ice-scales', 'Ice Scales', 'This Pokemon''s body is covered by crystal scales made of ice. Always cold to the touch, it easily deflects most projectiles, energy and light on its surface.', 'Reduce by 2 the Damage dealt to this Pokemon by All Special Moves.'),
    ('3.0', 'illuminate', 'Illuminate', 'The Pokemon naturally produces a soft and warm light through its body. Other Pokemon approach to it curiously when they see this light.', 'Increases the chance of random, non-hostile, wild Pokemon encounters. If there were enviromental challenges, or difficulty penalties due to reduced visibility, this Pokemon and it''s allies in range are immune to the effects.'),
    ('3.0', 'illusion', 'Illusion', 'The Pokemon casts an illusion on itself to look like another creature it has seen. The illusion is indistinguishable from the real one.', 'When this Pokemon comes out, it will have the form of another Pokemon in the party, the illusion breaks if it receives damage. Outside of battle it may cast the illusion on itself at will. Unique Ability.'),
    ('3.0', 'immunity', 'Immunity', 'The Pokemon has a very strong immune system and will rarely get sick. It could even eat rotten food without getting sick.', 'This Pokemon does not receive damage from Poison and Badly Poisoned Status Ailments.'),
    ('3.0', 'imposter', 'Imposter', 'This Pokemon can alter its own cell structure extremely fast to transform into a copy of another being.', 'As soon as it enters to battle, this Pokemon will be under the effects of the Move Transform (p.505).'),
    ('3.0', 'infiltrator', 'Infiltrator', 'The Pokemon is very stealthy with its movements, it is naturally harder to detect and can easily sneak in heavily guarded places.', 'This Pokemon ignores all Shield Moves, Force Fields, Substitutes and Cover active on the foe''s side of the field.'),
    ('3.0', 'innards-out', 'Innards Out', 'As it has no extremities, this Pokemon expels its own internal organs to use them as limbs or to defend itself from harm. Gross but effective.', 'If this Pokemon would faint due to damage from a Physical or Special Move, inflict damage on the attacker equal to the remaining HP the user had.'),
    ('3.0', 'inner-focus', 'Inner Focus', 'The Pokemon is extremely serious and focused on everything it does. It remains calm and never backs down, even if it''s getting severly injured.', 'This Pokemon does not Flinch. The Ability Intimidate does not have any effect against this Pokemon. Outside of battle this Pokemon is able to resist intimidation tactics, fear and stress better than others.'),
    ('3.0', 'insomnia', 'Insomnia', 'The Pokemon does not ever sleep, it will be awake no matter the hour. Maybe it doesn''t need to or maybe it''s just worried.', 'This Pokemon is immune to the Sleep Status. Moves and Items that self-inflict Sleep will fail.'),
    ('3.0', 'intimidate', 'Intimidate', 'This Pokemon has an overwhelming presence that inspires both fear and respect from others.', 'When this Pokemon comes into battle, Reduce by 1 the Strength of All foes in Range. This effect will last for as long as this Pokemon is out. Outside of battle, wild Pokemon will avoid the party if this Pokemon is out.'),
    ('3.0', 'intrepid-sword', 'Intrepid Sword', 'This audacious Pokemon is fearless to any challenge, its strength increases through sheer will. Its presence can be very menacing.', 'Whenever this Pokemon enters battle, Increase its Strength by 2. Outside of battle, this Pokemon can cut through any surface. Unique Ability'),
    ('3.0', 'iron-barbs', 'Iron Barbs', 'This Pokemon is covered with sharp steel quills that hurt anyone who may touch them carelessly', 'If this Pokemon is hit with a Non-Ranged Physical Move choose one: - Deal 1 Neutral Damage against the attacker. - Roll 2 Dice of Typeless Damage against the attacker.'),
    ('3.0', 'iron-fist', 'Iron Fist', 'The hands of this Pokemon are very strong and heavy, when curled into fists they can go through anything.', 'Add 1 Dice to the Damage Pool of Fist Based moves.'),
    ('3.0', 'justified', 'Justified', 'This Pokemon has an innate sense of justice, wrongdoings will make them really angry.', 'If a Dark-Type Move hits this Pokemon, Increase its Strength by 1. Up to 3 points can be increased this way.'),
    ('3.0', 'keen-eye', 'Keen Eye', 'These Pokemon have an exceptional sight. Locating small or far away objects is a lot easier for them.', 'This Pokemon cannot have successes removed from its Accuracy rolls by Moves, Items or Abilities.'),
    ('3.0', 'klutz', 'Klutz', 'This Pokemon does not understand how to use tools correctly, usually using them in unexpected ways.', 'Held items won''t have any effect on this Pokemon. Items that allow the Pokemon to Mega Evolve, use Z-Moves, go Dynamax/Gigantamax or Change type are not affected.'),
    ('3.0', 'leaf-guard', 'Leaf Guard', 'The leaves on this Pokemon''s body expand with the sun to completely cover and shield it from superficial damage. They may need to be pruned often.', 'While Sunny Weather is active, this Pokemon can''t have any Status Ailments or Conditions inflicted. Previously inflicted ailments/conditions remain.'),
    ('3.0', 'levitate', 'Levitate', 'The Pokemon floats to move around without ever touching the ground.', 'This Pokemon has immunity to Ground-Type moves and effects active on the battlefield such as Terrains and certain Entry Hazards.'),
    ('3.0', 'libero', 'Libero', 'This Pokemon always has its mind in the game. It will favor a defensive position and make the best special passes when it finally attacks.', 'Whenever this Pokemon is about to roll the Accuracy of a Move, change its type to match that of the Move. If the Move is Physical or Special and deals damage, use the appropriate STAB on the Damage Roll.'),
    ('3.0', 'light-metal', 'Light Metal', 'The Material covering its body will be light as a feather, causing this Pokemon to weigh half or even just a quarter of what it is supposed to.', 'Reduce the Pokemon''s weight at storyteller''s discretion. Moves with damage based on weight get their Damage Pool modified according to the reduced weight of the user.'),
    ('3.0', 'lightning-rod', 'Lightning Rod', 'This Pokemon will attract lightning and electricity to itself to charge its power. Great for preventing power surges. Bad for your electricity bill.', 'This Pokemon is immune to Electric-Type Damage. If anyone on the field uses a Single-Target Electric-Type Move, it will be redirected towards this Pokemon. The first time this Pokemon is hit by an Electric-Type move, Increase its Special by 1.'),
    ('3.0', 'limber', 'Limber', 'The muscles of this Pokemon are incredibly flexible and elastic. Easing their movement, agility, and grace.', 'This Pokemon is immune to Paralysis Status Ailment.'),
    ('3.0', 'lingering-aroma', 'Lingering Aroma', 'The Pokemon has a very strong smell, it may be pleasant or disgusting, but the smell will impregnate into everything and be very difficult to remove.', 'If this Pokemon hits or gets hit with a Non-Ranged Physical Move, the foe''s ability is changed to Lingering Aroma.'),
    ('3.0', 'liquid-ooze', 'Liquid Ooze', 'The Pokemon produces a pestilent and toxic ooze within its body. Do not attempt to eat it.', 'If this Pokemon is hit by a Move that would asborb it''s vital energy (Leech Seed, Mega Drain, Dream Eater, Drain Punch, etc.) it will deal damage to the foe instead of healing'),
    ('3.0', 'liquid-voice', 'Liquid Voice', 'Sound waves from its voice turn the moisture in the air into water, seemingly conjuring dew, rain, and even cascades out of a song.', 'All Sound-Based Moves this Pokemon uses are considered to be Water-Type.'),
    ('3.0', 'long-reach', 'Long Reach', 'The Pokemon is able to attack through the shadows of objects and foes meanwhile the real targets suffer the damage.', 'All Moves used by this Pokemon are considered to have the "Ranged" Added Effect'),
    ('3.0', 'magic-bounce', 'Magic Bounce', 'The Pokemon will use psychic control on its foe to make it indirectly harm itself, making it look like magic.', 'All Support Moves used by a foe that target this Pokemon or its side of the field will have their effects redirected into the foe''s instead.'),
    ('3.0', 'magic-guard', 'Magic Guard', 'The Pokemon is covered by a faint energy that stops any minor harm that comes its way. This gives the pokemon a bit of an ethereal glow in the dark.', 'The Pokemon only receives damage from Physical and Special Moves, Ongoing Damage, Confusion status, Pain Split, Destiny Bond, Perish Song & Self-Damaging Moves. Immune to damage from: Abilities, Status Ailments, Entry Hazards, Recoil, Held Items, or Weather. It can still have Status Ailments inflicted.'),
    ('3.0', 'magician', 'Magician', 'This Pokemon excells at performing simple magic tricks that amaze others, such as conjuring and vanishing objects nearby in the blink of an eye.', 'This Pokemon will steal the Held Item of a foe it just hit with a Physical or Special Move. If it already has a Held Item you may choose to switch it for the one it stole. For information on held Items see p.83.'),
    ('3.0', 'magma-armor', 'Magma Armor', 'The body of the Pokemon is always hot to the touch, it can heat a large room just by standing inside and can also endure high temperatures.', 'This Pokemon is immune to the Frozen Status Ailment. '),
    ('3.0', 'magnet-pull', 'Magnet Pull', 'This Pokemon can activate a magnetic field around itself to attract all kinds of metals and disrupt electric devices.', 'Other than the user, all Steel-Type Pokemon on the field are Blocked.'),
    ('3.0', 'marvel-scale', 'Marvel Scale', 'The beautiful scales of this Pokemon will harden when its body is under stress.', 'If this Pokemon has a Status Ailment, Increase its Defense Attribute by 2'),
    ('3.0', 'mega-launcher', 'Mega Launcher', 'The cannons on this Pokemon''s body allow it to fire extremely powerful attacks.', 'Add 2 Extra Dice to the Damage pool of moves with the keyword "Pulse" and "Aura" on their name. Healing Moves with the keyword "Pulse" become Complete Heals'),
    ('3.0', 'merciless', 'Merciless', 'Once this Pokemon senses weakness, it begins acting according to their brutal nature. They can be cruel if not put in their place.', 'If the Foe is inflicted with Poison or Badly Poison, all of this Pokemon Moves are considered to be Critical Hits. This Pokemon will not hold back when using Lethal Damage Moves at Storyteller''s discretion.'),
    ('3.0', 'mimicry', 'Mimicry', 'This Pokemon''s body is perfect for camouflaging in the ground. It can sometimes get lost but you will find it if some unfortunate victim steps on it.', 'If there is a Terrain Move active on the field (i.e. Electric Terrain, Psychic Terrain etc.) Change this Pokemon''s main type to match that of the active Terrain. Restore its original main type if the terrain effects end.'),
    ('3.0', 'mind''s-eye', 'Mind''s Eye', 'With an unparalleled cosmic awareness, this Pokemon is able to see the future accurately. It is said you can see your own demise by looking into its dead eye.', 'At night time, all Moves used by this Pokemon are considered to have the “Never Miss” Added Effect. It can hit Ghost-Type Pokemon with Normal-Type and Fight-Type Moves, dealing Regular Damage.'),
    ('3.0', 'minus', 'Minus', 'This Pokemon has a natural Negative charge. It will attract Positive charge and repel other negative charge. They are prone to feel blue.', 'If an ally Pokemon on the field has the ability "Plus" (p.559), Increase by 2 the Special Attribute of this Pokemon.'),
    ('3.0', 'mirror-armor', 'Mirror Armor', 'The Pokemon''s body is covered with a shiny armor. Said armor will repel and bounce back anything intending to weaken it.', 'All Effects Reducing Attributes/Traits used by a foe, that target this Pokemon or its side of the field will have their effects redirected into the foe''s instead.'),
    ('3.0', 'misty-surge', 'Misty Surge', 'The Pokemon can surround itself with a Misty Field that is eerily quiet, it feels peaceful and soothing but also lonesome and isolated.', 'When this Pokemon comes out, it automatically starts the effects of the Move Misty Terrain. (In case of stalemate the Pokemon with higher Will might keep the dominant Terrain)'),
    ('3.0', 'mold-breaker', 'Mold Breaker', 'This Pokemon will find unusual ways to achieve its goals. They are inventive and go around problems.', 'If a foe Pokemon has a Type, an immunity, or an Ability that would prevent this Pokemon from dealing Damage with a Move, ignore it.'),
    ('3.0', 'moody', 'Moody', 'The Pokemon will have some severe mood swings, and be temperamental most of the time. Hopefully it''s just a phase.', 'At the end of the Round, reset Attributes modified by Moody, then Reduce a random Attribute by 1 and Increase another random Attribute by 1. '),
    ('3.0', 'motor-drive', 'Motor Drive', 'This Pokemon absorbs electricity and stores it as energy to run faster or to power up machinery. An electric car''s best friend.', 'The first time this Pokemon is hit by an Electric-type move, Increase 1 Point to its Dexterity Attribute. This Pokemon doesn''t receive damage from Electric-type moves.'),
    ('3.0', 'moxie', 'Moxie', 'This Pokemon is naturally fierce and will try to get to a position of power by defeating the alphas in the pack.', 'If a foe faints because of a Physical or Special Move used by this Pokemon, Increase its Strength Attribute by 1. Up to 3 points can be increased this way.'),
    ('3.0', 'multiscale', 'Multiscale', 'This Pokemon is covered by two layers of hard scales, if one layer is damaged it will be shed and regrown later.', 'While this Pokemon at full health, Reduce by 1 the damage taken by the next Physical or Special Move it receives.'),
    ('3.0', 'multitype', 'Multitype', 'All the energies that created the universe flow raw through this Pokemon''s body and it harnesses whichever is more convenient at the moment.', 'Only Arceus may have this Ability. This Pokemon can freely change its Type at will in any moment of the battle. This Ability can''t be copied, switched, transfered, changed, ignored, or negated in any way. Unique Ability'),
    ('3.0', 'mummy', 'Mummy', 'This Pokemon will curse whoever dares to inflict harm upon them, the curse may even last for generations and will need the aid of a medium to lift it.', 'When this Pokemon hits or gets hit with a Non-Ranged Physical Move, the foe''s Ability is changed to Mummy. '),
    ('3.0', 'mycelium-might', 'Mycelium Might', 'The Pokemon releases invisible fungus spores continuosly, by the time you realize you have a complete fungal infestation around you.', 'All Support Moves used by this Pokemon are considered to have the "Never Miss" and "Late Reaction 1" Added Effect'),
    ('3.0', 'natural-cure', 'Natural Cure', 'This Pokemon''s body will generate substances to heal itself. They can be used to create medicine.', 'At the end of the Round, if this Pokemon has a Status Ailment or Condition, Roll 3 Chance Dice to heal it.'),
    ('3.0', 'neuroforce', 'Neuroforce', 'This Pokemon''s psychic power is overwhelming and can be felt even by simply standing nearby. It will exploit any weakness it finds in your mind.', 'This Pokemon will deal 1 Extra Damage on any Move that is Super Effective against a foe.'),
    ('3.0', 'neutralizing-gas', 'Neutralizing Gas', 'The Pokemon is surrounded by a sweet-smelling but noxious gas. Most people and Pokemon can''t help but to stop and smell it, though.', 'All foes in range will have the effects of their Abilities negated as long as this Pokemon is on the field.'),
    ('3.0', 'no-guard', 'No Guard', 'This Pokemon can focus on attacking perfectly but will be open to the attacks of its foes as it won''t focus on anything but its precision.', 'At the start of the Round, you may declare you won''t use Shield Moves, Evasion or Clash Maneuvers. If you do, roll all moves of this Pokemon as if they had no Low Accuracy.'),
    ('3.0', 'normalize', 'Normalize', 'The Pokemon''s actions are never impressive, always dull and never seem to accomplish anything exceptional.', 'All the moves known by this Pokemon are considered Normal-Type. Affecting STAB, weaknesses, immunities, and resistances. Add 1 Extra die of Damage Pool of Normal Moves.'),
    ('3.0', 'oblivious', 'Oblivious', 'This Pokemon will rarely have a satisfactory social interaction; too self-absorbed to take hints or cues in any relationship.', 'This Pokemon is not affected by the Love Status. It is immune to the effects of moves that affect its feelings such as Taunt, Charm, Captivate etc. at Storyteller''s discretion.'),
    ('3.0', 'opportunist', 'Opportunist', 'This Pokemon seizes any chance it has to gain something. They tend to be streetsmart and make use whatever little chance they get.', 'If a Pokemon on the foe''s side of the field increases a trait or Attribute, increase the same Trait or Attribute on this Pokemon. In case of stalemate, keep the highest number.'),
    ('3.0', 'orichalcum-pulse', 'Orichalcum Pulse', 'This Pokemon''s body is able to transform light waves into matter. Theory says that it''s bringing forth light that was emitted billions of years ago.', 'When this Pokemon comes out, it automatically starts the effects of the Sunny Weather. (In case of stalemate the Pokemon with higher Will might keep the dominant Terrain). While Sunny Weather is active, increase this Pokemon''s Strength Attribute by 2.'),
    ('3.0', 'overcoat', 'Overcoat', 'The Pokemon will have a protective coat surrounding its body that allows it to live under extreme weather conditions. Plus, it repels dust!', 'This Pokemon won''t recieve damage from Hail or Sandstorm weather. This Pokémon is immune to the added effects of Powder Moves.'),
    ('3.0', 'overgrow', 'Overgrow', 'When this Pokemon is hurt, it will grow huge plants on its body to defend itself, these plants are very strong but wither quickly.', 'Pain Penalization won''t reduce successes from Accuracy or Damage rolls of Grass-Type Moves used by this Pokemon. Grass-Type Moves get 2 Extra dice to their Damage Pool when this Pokemon is at half HP or less.'),
    ('3.0', 'own-tempo', 'Own Tempo', 'This Pokemon will do everything at its own pace, peer pressure will be ignored. Its behavior reflexive and calm... maybe too calm.', 'This Pokemon is not affected by the Confused Status Condition.'),
    ('3.0', 'parental-bond', 'Parental Bond', 'The Pokemon and its youngling are really close to each other, they do everything together. The parent is very protective.', 'All of the Damage Pools of this Pokemon get rolled twice. Choose the highest roll to deal damage to the foe.'),
    ('3.0', 'pastel-veil', 'Pastel Veil', 'The Pokemon is surrounded by a soft-colored glimmer. This energy feels pure and full of innocence. Unattainable and otherworldly.', 'User and Allies in range are immune to Poison and Badly Poison. If the condition was inflicted before this Pokemon came out, it remains.'),
    ('3.0', 'perish-body', 'Perish Body', 'This Pokemon silently curses those who cross it. Condemning their souls to suffer as it has suffered. Avoid this Pokemon, lest you suffer its grudge.', 'If this Pokemon is hit with Non-Ranged Physical Move, the foe will receive its remaining HP as damage and faint after three Rounds unless it is removed from battle.'),
    ('3.0', 'pickpocket', 'Pickpocket', 'The Pokemon will instinctively steal from others. It takes whatever it can when people are not looking.', 'If this Pokemon is not holding an Item it will steal the held Item of the foe it just hit with a Non-Ranged Physical Move.'),
    ('3.0', 'pickup', 'Pickup', 'This Pokemon will often gather objects and keep a small hoard of treasure it may share with you.', 'If this Pokemon was out of its Pokeball, at the end of the scene see what it found for you at Storyteller''s discretion. The higher the Rank of this Pokemon the more valuable the items it will find.'),
    ('3.0', 'pixilate', 'Pixilate', 'This Pokemon scatters fairy dust that brings happy thoughts to the mind. Everything it does looks incredibly adorable.', 'Normal-Type Moves that the Pokemon uses will deal damage as if they were Fairy-Type. Affecting STAB, weakness and resistance. Add 1 Extra die to the Damage Pool of Fairy Moves.'),
    ('3.0', 'plus', 'Plus', 'This Pokemon has a natural Positive charge. It will attract negative charge and repel other positive charge. It has a red blush all the time.', 'If an ally Pokemon has the ability "Minus", Increase by 2 the Special Attribute of this Pokemon.'),
    ('3.0', 'poison-heal', 'Poison Heal', 'The Pokemon has an immunity to any poison and also assimilates venom as an energy source.', 'If this Pokemon becomes poisoned or badly poisoned. It will Heal 1 HP at the end of each round instead of receiving damage. The Poison will be completely absorbed and healed after 3 Rounds.'),
    ('3.0', 'poison-point', 'Poison Point', 'The pointy thorns and scales on this Pokemon release a venom that will infect anyone who touches them roughly. Wear gloves when handling them.', 'If this Pokemon is hit by a Non-Ranged Physical Move, Roll 3 Chance Dice to inflict Poison on the foe.'),
    ('3.0', 'poison-puppeteer', 'Poison Puppeteer', 'The Pokemon secrets a powerful neurotoxin, its venom won''t only damage the body of foes but their minds as well.', 'If a Target gets the Poison or Badly Poison Status ailments as the direct result of a Move used by this Pokemon, inflict Confusion on them as well. Unique Ability.'),
    ('3.0', 'poison-touch', 'Poison Touch', 'Venomous substances will ooze through the body of this Pokemon, you''ll become very sick if it touches you.', 'If this Pokemon hits a foe with a Non-Ranged Physical Move, Roll 2 Chance Dice to Inflict Poison on the foe.'),
    ('3.0', 'power-construct', 'Power Construct', 'Small cells gather around this Pokemon and are absorbed into its body. It grows bigger and stronger as more cells come together.', 'At the end of the Round, if this Pokemon has half or less of its HP, change its Form to the next one. When this Pokemon changes Form, remove Status Ailments & restore its full HP & Will. Unique Ability.'),
    ('3.0', 'power-of-alchemy', 'Power of Alchemy', 'This Pokemon can absorb the essence of everything it touches, fusing with the chemical composition and even the genes of discarded trash.', 'For the next 24 Hours the Pokemon copies the ability of a fainted Ally. Multiple Abilities may be copied this way, but only one may be active during combat. Unique Ability.'),
    ('3.0', 'power-spot', 'Power Spot', 'The Pokemon releases a mysterious energy that messes up with electronics and compasses but can somehow make you feel very energized.', 'Add 1 Extra die to the Damage Pools from Physical and Special Moves by Allies in Range. This Effect does not stack in the same Allies if multiple Pokemon have this Ability.'),
    ('3.0', 'prankster', 'Prankster', 'This Pokemon will always have a mischievous twinkle in its eyes, no one around will be safe from its pranks.', 'All Support Moves used by this Pokemon are considered to have: "Reaction 1" as Added Effect.'),
    ('3.0', 'pressure', 'Pressure', 'Being around this Pokemon will be very stressing and demanding, only the bravest dare to face them one-on-one.', 'When this Pokemon comes out, All foes in Range spend half (rounded up) of their remaining Will Points without gaining any effect for it. This effect does not stack.'),
    ('3.0', 'primordial-sea', 'Primordial Sea', 'The torrential rain barely lets you breathe, the field quickly becomes flooded and you must swim to stay afloat. No fire can be ignited at a time like this.', 'When this Pokemon comes out, it automatically starts the effects of Typhoon Weather. The effects end when the Pokemon leaves the battle. (In case of stalemate, The Pokemon with highest Will might keep the dominant weather). Unique Ability.'),
    ('3.0', 'prism-armor', 'Prism Armor', 'This Pokemon''s body is an incredibly resilient armor. It can withstand even hits that should shatter it into pieces.', 'Reduce by 2 the total Damage dealt to this Pokemon by a Super Effective Move.'),
    ('3.0', 'propeller-tail', 'Propeller Tail', 'The Pokemon''s tail allows it to maneuver very easily while in the water. It has no problem making sudden sharp turns to pursue and catch its prey.', 'Ignore the effects of Moves or Abilities that would change this Pokemon''s Moves into another target. (i.e. The Move "Follow Me", the Ability "Lightining Rod" etc.)'),
    ('3.0', 'protean', 'Protean', 'This Pokemon''s versatile body gives it proficiency on practically everything it sets out to do.', 'Before this Pokemon uses a Physical or Special Move, change its Type to that of the Move it intends to use. Use the appropriate STAB on the Damage Pool.'),
    ('3.0', 'protosynthesis', 'Protosynthesis', 'This Pokemon''s primal energy is barely contained. Sunlight powers them up and brings up a wilder and savage behaviour.', 'While Sunny Weather is active, increase this Pokemon''s highest Attribute by 1. If their highest Attribute is Dexterity, increase it by 2. Unique Ability.'),
    ('3.0', 'psychic-surge', 'Psychic Surge', 'The Pokemon can surround itself with a psychic field that makes everyone pause, hearing things that are not there.', 'When this Pokemon comes out, it automatically starts the effects of the Move Psychic Terrain. (In case of stalemate the Pokemon with higher Will might keep the dominant Terrain)'),
    ('3.0', 'punk-rock', 'Punk Rock', 'The Pokemon loves music and loud noises. It is constantly jamming with its air guitar and can easily improvise a music number out of nothing.', 'Sound-Based Moves this Pokemon uses get 1 Extra die to their Damage Pool. Sound-Based Moves used against this Pokemon have their total Damage reduced by 2.'),
    ('3.0', 'pure-power', 'Pure Power', 'The Pokemon makes use of its psychic powers to move objects several times bigger.', 'This Pokemon has a permanent increase to its Strength Attribute. Ranks Starter, Rookie, Standard, and Advanced Increase Strength by 1. Rank Expert and higher Increase Strength by 2.'),
    ('3.0', 'purifying-salt', 'Purifying Salt', 'The Pokemon produces a high quality salt that wards off against any bacteria, impurity, and even keep those pesky evil spirits at bay.', 'This Pokemon can''t have any Status Ailment inflicted on them. Previously inflicted Ailments remain. Ghost-Type Moves used against this Pokemon have their total Damage Reduced by 3.'),
    ('3.0', 'quark-drive', 'Quark Drive', 'This Pokemon is energized to a sub-atomic level, its power barely contained. A power grid could destabilize their elecron charge out of this dimension.', 'If Electric Terrain is active, increase this Pokemon''s highest Attribute by 1. If their highest Attribute is Dexterity, increase it by 2. Unique Ability.'),
    ('3.0', 'queenly-majesty', 'Queenly Majesty', 'This Pokemon''s presence commands awe and respect. Others have no choice but to do as it says, whoever tries to outplay it, will feel its discontent', 'Foes cannot use Reaction Moves against this Pokemon.'),
    ('3.0', 'quick-draw', 'Quick Draw', 'This Pokemon shot first. They edited it to look like it didn''t, but we know it shot first!', 'Roll 3 Chance Dice at the beginning of each Round. If successful, this Pokemon goes first in the initiative order of that Round. In ccase of stalemate, regular initiative order prevails.'),
    ('3.0', 'quick-feet', 'Quick Feet', 'Most of the time this Pokemon will seem to be in a hurry. When pressured, it will move faster than normal.', 'While affected by a Status Ailment (Burn, Frozen, Paralysis, Poison, Sleep), Increase this Pokemon''s Dexterity Attribute by 2. If inflicted by Paralysis, this Ability prevents its effects.'),
    ('3.0', 'rain-dish', 'Rain Dish', 'The Pokemon will store rain water for drink and nourishment.', 'While Rain Weather is active, you may restore 1 HP to this Pokemon at the end of each Round.'),
    ('3.0', 'rattled', 'Rattled', 'When this scaredy Pokemon becomes startled or scared it will make haste to get away from danger.', 'The first time this Pokemon is hit by a Bug, Dark, or Ghost-Type Move, or if a foe has the Ability "Intimidate", Increase its Dexterity Attribute by 1.'),
    ('3.0', 'receiver', 'Receiver', 'This Pokemon is used to learning the tactic behavior of other Pokemon with which they have a bond.', 'For the next 24 Hours the Pokemon copies the ability of a fainted Ally. Only one Ability may be copied this way. Unique Ability.'),
    ('3.0', 'reckless', 'Reckless', 'The Pokemon will often get into risky situations in order to get what it wants. They are prone to risk their lives without thinking of the consequences.', 'When this Pokemon performs a Move with Recoil as an Added Effect, Add 2 Extra dice to the Damage Pool of that Move.'),
    ('3.0', 'refrigerate', 'Refrigerate', 'This Pokemon''s body works akin to a freezer, it can freeze things just by touching them.', 'Normal-Type Moves that the Pokemon uses will deal damage as if they were Ice-Type. Affecting STAB, weakness and resistance. Add 1 Extra die to the Damage Pool of Ice moves.'),
    ('3.0', 'regenerator', 'Regenerator', 'The body of this Pokemon will regenerate from damage really quick, wounds that would take days to heal will get better in a few hours.', 'This Pokemon may Heal up to 4 HP or up to 2 HP in case of Lethal Damage on its own every day. The Pokemon must be out of combat to benefit from this effect.'),
    ('3.0', 'ripen', 'Ripen', 'The Pokemon can ripen fruits and berries in no time to make them Extra sweet and delicious, healing berries will have their effects boosted.', 'Moves that use berries for Added Effects will have 2 Extra Dice on their Damage Pool (i.e. "Natural Gift" etc.) Increase the Healing properties of Berries at Storyteller''s discretion.'),
    ('3.0', 'rivalry', 'Rivalry', 'The Pokemon will be very competitive with others to prove its position as the alpha of the group, however, it will try to gain the favor of possible mates.', 'If this Pokemon targets a foe of the same gender, Increase its Strength Attribute by 1. If the targeted foe is the opposite gender, Reduce its Strength Attribute by 1.'),
    ('3.0', 'rks-system', 'RKS System', 'The Pokemon''s physiology morphs according to the data disc inserted in its RKS-drive. There are 17 discs, one for each Type. (No disc is Normal Type).', 'Change the Pokemon''s Type to match the Disc on its Held Item slot. (i.e. Electric Disc makes this Pokemon become an Electric Type). Unique Ability.'),
    ('3.0', 'rock-head', 'Rock Head', 'The head and body of the Pokemon are so resistant that they barely feel anything. Careful as they bump into things without even noticing.', 'This Pokemon will not receive damage from Recoil.'),
    ('3.0', 'rocky-payload', 'Rocky Payload', 'The Pokemon always carries a hidden stash of rocks. It has the bad habit of making them fall on top of others.', 'All Physical or Special Rock-Type Moves this Pokemon uses get 1 Extra die to their Damage Pool.'),
    ('3.0', 'rough-skin', 'Rough Skin', 'Use protection on your hands when touching this Pokemon. Its body is covered by sharp scales or barbs that get hooked into the skin.', 'If this Pokemon is hit with a Non-Ranged Physical Move choose one: - Deal 1 Neutral Damage against the attacker. - Roll 2 Dice of Typeless Damage against the attacker.'),
    ('3.0', 'run-away-ability', 'Run Away', 'This Pokemon is a master of escape. It will be difficult to catch as it can squeeze through the tiniest gaps to get away.', 'This Pokemon cannot be Blocked. It may also obtain bonus dice to escape from battle, Pokeballs or captivity at Storyteller''s discretion.'),
    ('3.0', 'sand-force', 'Sand Force', 'The Pokemon controls the particles of sand around the battlefield to give a boost to its attacks.', 'While Sandstorm Weather is active, if this Pokemon uses a Physical or Special Ground, Steel or Rock-Type Move, add 1 Extra die to the Damage Pool of that Move. The Pokemon is immune to damage from Sandstorm Weather.'),
    ('3.0', 'sand-rush', 'Sand Rush', 'While sand whips across the battlefield, the Pokemon can paddle through it as if it was water.', 'While Sandstorm Weather is active, increase the Dexterity Attibute of this Pokemon by 1. The Pokemon is immune to damage from Sandstorm Weather.'),
    ('3.0', 'sand-spit', 'Sand Spit', 'The Pokemon slithers through the desert sand, eating some of it in the process, if it gets hit (or sneezes) a sandstorm will blow up.', 'If this Pokemon is hit with a Non-Ranged Physical Move, it starts the effects of Sandstorm Weather. The effect lasts 4 rounds. This effect does not reactivate until the Sandstorm Weather is removed.'),
    ('3.0', 'sand-stream', 'Sand Stream', 'The Pokemon can activate a raging sandstorm around itself that will last for as long as it wants.', 'When this Pokemon comes out, it automatically starts the effects of Sandstorm Weather. The effects end when the Pokemon leaves the battle. (In case of stalemate the Pokemon with higher Will, might keep the dominant weather)'),
    ('3.0', 'sand-veil', 'Sand Veil', 'The Pokemon''s body is easily concealed by sand particles in the air.', 'While Sandstorm Weather is active, this Pokemon can use the Evasion Maneuver up to 5 times per Round. The Pokemon is immune to damage from Sandstorm weather.'),
    ('3.0', 'sap-sipper', 'Sap Sipper', 'This Pokemon''s diet consists strickly of plants, it is particularly fond of sweet sap for nourishment.', 'The first time this Pokemon is hit by a Grass-type attack, Increase its Strength Attribute by 1 instead of dealing damage. Grass-type moves do not deal damage to this Pokemon.'),
    ('3.0', 'schooling', 'Schooling', 'When this Pokemon is threatened, it calls thousands of allies to create an uncontrollable monster. The closer to the sea, the faster they arrive.', 'When this Pokemon is at half HP or less it will call for its Allies, when the Allies arrive replace the change to Wishiwashi School-Form at full HP. Increase its Rank two above your own. Restore Wishiwashi base Form at the end of the battle. Healing/Fainting/Recalling prevents the allies from arriving. Unique Ability.'),
    ('3.0', 'scrappy', 'Scrappy', 'This Pokemon does not believe in ghosts.', 'This Pokemon can hit Ghost-type Pokemon with Normal and Fighting Type Moves. Apply resistances or weaknesses to the foe if it has a secondary type.'),
    ('3.0', 'screen-cleaner', 'Screen Cleaner', 'This Pokemon is constantly cleaning an invisible screen, it cleans them so well that even real glass screens can disappear after it is done with them.', 'When this Pokemon enters the field, remove any active Force Fields (i.e. Light Screen, Reflect etc.) on both sides of the field.'),
    ('3.0', 'seed-sower', 'Seed Sower', 'The Pokemon leaves a trail of sapling sprouts wherever it goes. Hitting or shocking it will make a rain of seeds fall to the ground.', 'If this Pokemon is hit with a Physical or Special Move, it starts the effects of Grassy Terrain. The effect lasts 4 rounds. This effect does not reactivate until the Terrain is removed.'),
    ('3.0', 'serene-grace', 'Serene Grace', 'This Pokemon will bring good luck as if it was blessed by the heavens. Its presence is soothing, it makes you feel calm and full of joy.', 'This Pokemon adds 2 Extra Chance Dice to all Moves with effects that use them. (e.g. A move has 3 Chance Dice to Flinch the foe, this Pokemon will roll 5 Dice)'),
    ('3.0', 'shadow-shield', 'Shadow Shield', 'When it is at full strength, this Pokemon''s ghostly body cannot be touched or pierced by anything, it can even go through walls as if they weren''t there.', 'If this Pokemon is at full health, Reduce by 2 the damage dealt by the next Physical or Special Move targeting it. This effect cannot be ignored by Moves or Abilities.'),
    ('3.0', 'shadow-tag', 'Shadow Tag', 'The Pokemon can physically take a hold of shadows to make them act on their own or capture their victims.', 'All Targets in Range become Blocked. Ghost-type Pokemon are immune to this effect. Pokemon with the same ability are immune to this effect.'),
    ('3.0', 'sharpness', 'Sharpness', 'This Pokemon''s scales are laminated and its edges are incredibly sharp, allowing them to cut through ropes, nets and foes with ease.', 'Add 1 Extra die to the Damage Pool of all Cutter Moves.'),
    ('3.0', 'shed-skin', 'Shed Skin', 'This Pokemon''s body is constantly growing skin anew and molting the old one when it becomes too damaged.', 'At the end of the round, if this Pokemon has a Status Ailment/Condition, Roll 3 Chance Dice to heal it. If affected by multiple Ailments/Conditions, one will be healed at random.'),
    ('3.0', 'sheer-force', 'Sheer Force', 'This Pokemon is only interested in showing off its incredible battle prowess.', 'Whenever this Pokemon uses a Physical or Special Move with Added Effects, you may choose to ignore them and add 2 Extra Dice to the Damage Pool instead. Added Effects from Items trigger this effect but do not stack.'),
    ('3.0', 'shell-armor', 'Shell Armor', 'This Pokemon''s shell protects its vulnerable spots from its opponents.', 'Whenever a foe lands a Critical Hit on this Pokemon, it won''t get Bonus Damage Dice for that attack.'),
    ('3.0', 'shield-dust', 'Shield Dust', 'This Pokemon constantly generates specs of dust to shield and protect itself.', 'This Pokemon is not affected by any effects triggered by Chance Dice of foes.'),
    ('3.0', 'shields-down', 'Shields Down', 'The Pokemon''s core is protected by a sturdy shield, if the shield is shattered the Pokemon starts acting crazy.', 'Only Minior can use this Ability. After reaching half or less of its HP in battle, replace Minior by Minior (Core) at full HP. While in Core Form this Pokemon is Immune to Status Ailments. To restore it to its base form, the core must be set free and then recaptured after it returns a few days later. Unique Ability'),
    ('3.0', 'simple', 'Simple', 'This Pokemon''s ingenious mind is easily swayed by not only its own, but also outside influences. It often finds the most simple solution to a problem.', 'If this Pokemon gets an Attribute reduced, reduce it by 1 more Point. If this Pokemon gets an Attribute increased, increase it by 1 more Point.'),
    ('3.0', 'skill-link', 'Skill Link', 'This Pokemon can proficiently chain a flurry of attacks and it is one heck of a juggler. It also enjoys repetition and sequences.', 'Add 2 Extra Dice to the Accuracy roll of all Double, Triple, or Successive Actions this Pokemon use.'),
    ('3.0', 'slow-start', 'Slow Start', 'The Pokemon has remained dormant for thousand of years, its movements are heavy and slow, run away before it unleashes its full power.', 'During the first three Rounds of a battle, this Pokemon will always go last in the initiative order. After those Rounds are over, Increase its Strength and Dexterity Attributes by 2 and now it will always go first in the initiative order. This effect resets if the Pokemon is called out of combat.'),
    ('3.0', 'slush-rush', 'Slush Rush', 'The Pokemon is used to run and hunt on icy terrain, moving swiftly through the snow during blizzards and ice storms.', 'While Hail/Snow Weather is active, increase the Dexterity Attribute of this Pokemon by 2. The Pokemon is immune to damage from Hail/Snow Weather.'),
    ('3.0', 'sniper', 'Sniper', 'This Pokemon will stealthily locate itself in an advantageous position to strike its foe''s weak spots.', 'When this Pokemon lands a Critical Hit, it will get 3 Bonus Dice to the Damage Pool of its Move instead of the regular 2.'),
    ('3.0', 'snow-cloak', 'Snow Cloak', 'This Pokemon''s skin blends well with the surrounding snow and hail, you can barely see it.', 'While Hail/Snow Weather is active, this Pokemon can use the Evasion Maneuver up to 5 times per Round. The Pokemon is immune to damage from Hail/Snow weather.'),
    ('3.0', 'snow-warning', 'Snow Warning', 'The Pokemon is able to call a terrible hailstorm at will. Snow will cover the battlefield and sharp ice shards will come plummeting from the sky.', 'When this Pokemon comes out, it automatically starts the effects of Hail/Snow Weather. The effects end when the Pokemon leaves the battle. (In case of stalemate the Pokemon with higher Will might keep the dominant weather)'),
    ('3.0', 'solar-power', 'Solar Power', 'The Pokemon is capable of overcharging itself with energy from the sun, making it more powerful but also taking a toll on its body.', 'While Sunny Weather is active, Increase this Pokemon''s Special Attribute by 2 and deal 1 damage to it at the end of the Round.'),
    ('3.0', 'solid-rock', 'Solid Rock', 'This Pokemon''s body is composed of extremely hard rock, protecting it from everything, even its own weaknesses.', 'If this Pokemon is hit by a Move that is Super-Effective, reduce by 1 the total Damage dealt to it.'),
    ('3.0', 'soul-heart', 'Soul Heart', 'This Pokemon is naturally caring and nurturing and if there''s a threat to its loved ones, its soul will be made stronger out of love.', 'If a foe faints because of a Physical or Special Move used by this Pokemon, Increase its Special Attribute by 1. Up to 3 points can be increased this way.'),
    ('3.0', 'soundproof', 'Soundproof', 'This Pokemon''s body is structured to protect it from noises that might disturb its peace and focus. So it''s not ignoring you, it just can''t hear you.', 'This Pokemon is immune to the Damage and Added Effects of all Sound-based moves.'),
    ('3.0', 'speed-boost', 'Speed Boost', 'This Pokemon will start maneuvering at an accelerated rate, it will move as if it blinked from place to place.', 'At the end of the Round, Increase this Pokemon''s Dexterity Attribute by 1. Up to 3 Points might be added this way.'),
    ('3.0', 'stakeout', 'Stakeout', 'The Pokemon is constantly surveilling its environment, looking out for possible prey, attacking them when they are most vulnerable.', 'Whenever a foe Pokemon is switched out this Pokemon will inflict 1 Extra Damage on its first successful attack to the newly switched in foe.'),
    ('3.0', 'stall', 'Stall', 'This Pokemon is indecisive and always lets others act first before making its mind on what action to take.', 'This Pokemon always goes last in the the initiative order.'),
    ('3.0', 'stalwart', 'Stalwart', 'The Pokemon naturally has a high sense of duty and loyalty, once you give it a task it will not stay until its quest is complete.', 'Ignore any Moves or Abilities that would redirect this Pokemon''s Moves into another Target. (i.e. The Move "Follow Me", the Ability "Lightning Rod" etc.)'),
    ('3.0', 'stamina', 'Stamina', 'This Pokemon cannot get tired. It regains its fortitude when it feels weak. Even when it barely eats or sleeps.', 'The first time this Pokemon receives Damage from a Physical or Special Move, Increase its Defense and Special Defense by 1.'),
    ('3.0', 'stance-change', 'Stance Change', 'This Pokemon can change forms and become a mighty shield or a powerful blade. Its attributes switch upon a change of stance.', 'Only Aegislash may use this Ability. At the beginning of the round, choose a Form. While in Sword Stance it can only use Physical or Special Moves. While in Shield Stance, it can only use Support Moves. Adjust its Attributes according to the Rank and Limits it has for each Form. Keep the highest HP shared for both forms.'),
    ('3.0', 'static', 'Static', 'This Pokemon''s body is always ready to let off a jolt of static electricity at the slightest touch.', 'When hit by a Non-Ranged Physical Move, this Pokemon rolls 3 Chance Dice to inflict Paralysis on the foe.'),
    ('3.0', 'steadfast', 'Steadfast', 'This Pokemon may have a stern exterior but it is reliable and even more when adversity strikes.', 'The first time this Pokemon is affected by Flinch, Increase its Dexterity Attribute by 1.'),
    ('3.0', 'steam-engine', 'Steam Engine', 'The Pokemon works as a steam furnace, with a bit of fire and water it can move anything at great speeds. It also loves to eat coal.', 'The first time this Pokemon is dealt damage with a Fire or Water-Type Move. Increase 3 Points to its Dexterity Atribute.'),
    ('3.0', 'steelworker', 'Steelworker', 'The Pokemon is capable of molding and eating steel, giving shape and a sharper edge to any metal it touches.', 'Steel-Type Moves used by this Pokemon get 1 Extra Die to their Damage Pool.'),
    ('3.0', 'steely-spirit', 'Steely Spirit', 'The Pokemon has a balky behaviour most of the time. if it sets its mind to something it will see it done. Infuriating and inspiring at the same time.', 'Steel-Type Moves used by this Pokemon and Allies in Range get 1 Extra Die to their Damage Pool.'),
    ('3.0', 'stench', 'Stench', 'This Pokemon can emit a smell so unpleasant it repels other people and Pokemon.', 'Reduce the chance of wild Pokemon encounters at Storyteller''s discretion. Whenever this Pokemon is hit with a Non-Ranged Physical Move, Roll 1 Chance Die to Flinch the foe. '),
    ('3.0', 'sticky-hold', 'Sticky Hold', 'This Pokemon''s body is always oozing adhesive substances, if something gets glued, it will be very difficult to remove.', 'This Pokemon''s Held Item cannot be removed, stolen or swapped by Moves or Abilities.'),
    ('3.0', 'storm-drain', 'Storm Drain', 'The Pokemon absorbs moisture and liquids like a sponge, then uses them to increase its power and last more time outside of water.', 'This Pokémon is immune to Water-Type Damage. If another Pokémon on the field uses a Single-Target Water-Type Move, it will be redirected towards this Pokémon. The first time this Pokémon is hit by a Water-Type move, Increase its Special by 1.'),
    ('3.0', 'strong-jaw', 'Strong Jaw', 'The Pokemon''s strong jaw gives it tremendous biting power. Its teeth can tear through almost anything.', 'Add 1 Extra Die to the Damage Pool of all Bite Moves.'),
    ('3.0', 'sturdy', 'Sturdy', 'This Pokemon''s body is extremely resistant to damage, it can withstand almost anything.', 'The first time this Pokemon would reach 0 HP due to damage from a Move, it will remain at 1 HP instead. Status Ailments/Conditions, Weather, and Self-inflicted damage do not trigger this effect. The Pokemon can only benefit from Sturdy once per scene.'),
    ('3.0', 'suction-cups', 'Suction Cups', 'This Pokemon''s limbs contain suckers that allow it to stay rooted in place. It can stick to any kind of surface, even upside down.', 'The Pokemon is immune to effects that force switches from foes. Outside of battle, reduce difficulty to catch wet and/or slippery Pokemon at Storyteller''s discretion.'),
    ('3.0', 'super-luck', 'Super Luck', 'This Pokemon has an incredible good luck, good things happen to it regularly.', 'All Physical and Special Moves of this Pokemon have "High Critical" as an Added Effect. If the Move already had "High Critical" the effect stacks and this Pokemon only requires 1 more Success on the Accuracy roll to land a Critical instead of 2.'),
    ('3.0', 'supersweet-syrup', 'Supersweet Syrup', 'This Pokemon is incredibly sweet in both demeanor and flavour. Many find it irresistible to lick it, trying to reach its center.', 'Increase the chance of wild Pokemon encounters at Storyteller''s discretion. All foes in Range cannot evade Moves performed by this Pokemon.'),
    ('3.0', 'supreme-overlord', 'Supreme Overlord', 'This Pokemon has a commanding aura and is obsessively ridden with the need to rule over everything, even the ashes of a kingdom.', 'When this Pokemon comes into battle, Increase its Strength and Special Attributes by 1 for every Ally that has Fainted in-battle. Up to 3 points can be increased this way.'),
    ('3.0', 'surge-surfer', 'Surge Surfer', 'This Pokemon''s magnetic field allows it to stand and surf on top of electric currents as if it were floating.', 'While Electric Terrain is active, increase this Pokemon''s Dexterity Attribute by 2.'),
    ('3.0', 'swarm', 'Swarm', 'The Pokemon enters a hive mind state when its life is on the line, calling upon a swarm to aid it in battle.', 'Pain Penalization won''t reduce successes from Accuracy or Damage rolls of Bug-Type Moves used by this Pokemon. Bug-Type Moves get 2 Extra dice to their Damage Pool when this Pokemon is at half HP or less.'),
    ('3.0', 'sweet-veil', 'Sweet Veil', 'This Pokemon''s delicious aroma will wake the appetite of all Pokemon nearby.', 'Increase the chance of wild Pokemon encounters at Storyteller''s discretion. The Pokemon and allies in range are immune to the Sleep status.'),
    ('3.0', 'swift-swim', 'Swift Swim', 'The Pokemon will move faster in water than on land, even a puddle-covered roadway will allow it to use its full speed.', 'While Rain Weather is active, Increase this Pokemon''s Dexterity Attribute by 2.'),
    ('3.0', 'sword-of-ruin', 'Sword of Ruin', 'There is a cursed artifact on this Pokemon. A cold hatred takes harbor inside everyone''s hearts. This Pokemon loves to instigate conflict amongst others.', 'Reduce by 2 the Defense of everyone in the field, except this Pokemon. This Pokemon is immune to the effects of the Abilities: Beads of Ruin, Sword of Ruin, Tablets of Ruin, and Vessel of Ruin. Unique Ability.'),
    ('3.0', 'symbiosis', 'Symbiosis', 'This Pokemon enjoys forming a mutually-beneficial relationship with any ally it teams up with.', 'If an ally loses or spends its Held Item, this Pokemon will immediately give the one it''s holding to the ally as a free action. '),
    ('3.0', 'synchronize', 'Synchronize', 'The Pokemon can share its mood, feelings and sensations with others, specially with those who caused it pain.', 'Whenever a foe inflicts a Status Ailment or Condition to this Pokemon, the same Status is inflicted into the foe. this Ability does not ignore a foe''s immunity to certain Status Ailments/Conditions.'),
    ('3.0', 'tablets-of-ruin', 'Tablets of Ruin', 'There is a cursed artifact on this Pokemon. A putrid moldy sickness consumes everyone''s body. This Pokemon loves to enfeeble and weaken others.', 'Reduce by 2 the Strength of everyone in the field, except this Pokemon. This Pokemon in immune to the effects of the Abilities: Beads of Ruin, Sword of Ruin, Tablets of Ruin, and Vessel of Ruin. Unique Ability.'),
    ('3.0', 'tangled-feet', 'Tangled Feet', 'The Pokemon moves in a very strange and particular way when dizzy or confused, this usually works to its advantage.', 'While this Pokemon is Confused, Add Extra "Reduced Accuracy" to all of the foe''s Moves that Target this Pokemon.'),
    ('3.0', 'tangling-hair', 'Tangling Hair', 'This Pokemon''s hair is thick and tough, it easily tangles anyone who comes close to it. Brush it twice a day to keep it silky and shiny.', 'The first time a foe hits this Pokemon with a Non-Ranged Physical Move, Reduce its Dexterity Attribute by 1.'),
    ('3.0', 'technician', 'Technician', 'This Pokemon is meticulous and precise in tasks that everyone else would perform roughly and without care.', 'Add 1 Extra die to the Damage pool of all Physical or Special Moves with Power 1 or 2 this Pokemon performs.'),
    ('3.0', 'telepathy', 'Telepathy', 'This Pokemon can communicate using telepathy. It can send messages to other minds but it cannot receive messages back.', 'This Pokemon won''t receive damage from Moves performed by its allies.'),
    ('3.0', 'tera-shell', 'Tera Shell', 'Few Pokemon witnessed Arceus bestow the universe with energy, from them only one managed to encompass a piece of it all within itself.', 'Only Terapagos may use this Ability. While this Pokemon is at full health it receives Not-Very-Effective Damage from all Physical or Special Moves. Unique Ability'),
    ('3.0', 'tera-shift', 'Tera Shift', 'There is a flow of energy within this Pokemon that encompases all Types in existance. This energy is as old as the universe itself.', 'Only Terapagos may use this Ability. At the beginning of a new Round, you may change Terapagos into its Terastral Form, if you do, Restore its full HP, Will, and heal it from any Status. Unique Ability.'),
    ('3.0', 'teraform-zero', 'Teraform Zero', 'In this form, Terapagos once held the newly-created world on top of itself. It is well within its power to restore it to its most ancient state.', 'Only Terapagos may use this Ability. Remove all Active Effects on the battlefield and negate any Effect on the Battlefield while this Pokemon is out. (Force Fields, Entry Hazards, Terrain, Weather, Abilities etc.) Unique Ability.'),
    ('3.0', 'teravolt', 'Teravolt', 'There''s a ball of blue lightning coming out of this Pokemon that prevents its foes from being out of reach, no matter what you do, it will zap you.', 'If a Type, Move, Item or Ability would prevent this Pokemon from targeting a foe or inflicting an effect, ignore it. (e.g. A Pokemon with Immunity can be Poisoned, Ground-Type Pokemon can be hit with Electric Moves, etc.) Unique Ability.'),
    ('3.0', 'thermal-exchange', 'Thermal Exchange', 'This Pokemon''s body is so gelid it violently reacts to any sudden temperature change.', 'This Pokemon is immune to all Burn degrees. The first time this Pokemon is hit by a Fire-Type Move, Increase its Strength Attribute by 1. This effect does not prevent damage from Fire-Type Moves.'),
    ('3.0', 'thick-fat', 'Thick Fat', 'This Pokemon''s body has a thick layer of blubber that protects it against against harsh temperatures.', 'Reduce by 1 the damage taken from Fire and Ice-Type moves.'),
    ('3.0', 'tinted-lens', 'Tinted Lens', 'This Pokemon''s goggle-like eyes can find the good side in every bad situation, even when there is none.', 'If a foe has a Type resistance to a Move performed by this Pokemon, ignore it. If the foe has a double Type resistance, only one resistance can be ignored.'),
    ('3.0', 'torrent', 'Torrent', 'This Pokemon builds up pressure to shoot water streams. When that pressure cannot be held in, it is released through uncontrollable torrents.', 'Pain Penalization won''t reduce successes from Accuracy or Damage rolls of Water-Type Moves used by this Pokemon. Water-Type Moves get 2 Extra dice to their Damage Pool when this Pokemon is at half HP or less.'),
    ('3.0', 'tough-claws', 'Tough Claws', 'This Pokemon''s claws are so sturdy, they can tear through almost anything.', 'Add 1 Extra die to the Damage Pool of all non-Ranged Physical Moves this Pokemon performs.'),
    ('3.0', 'toxic-boost', 'Toxic Boost', 'The blood of this Pokemon boils whenever it is afflicted by Poison, this fever induces an uncontrollable rage.', 'If this Pokemon gets the Poison or Badly Poison Status, Increase its Strength Attribute by 2.'),
    ('3.0', 'toxic-chain', 'Toxic Chain', 'The chain that binds this Pokemon is both corroded and corrosive as a result of their greed that can poison the spirit and mind as well as your body.', 'If this Pokemon hits a foe with a Non-Ranged Physical Move, Roll 3 Chance Dice to Inflict Badly Poison on the foe.'),
    ('3.0', 'toxic-debris', 'Toxic Debris', 'This Pokemon can encapsulate toxins inside the layers of brittle crystal covering its body, be careful not to shatter it.', 'If this Pokemon is hit with a Non-Ranged Physical Move, scatter Toxic Spikes (p.509) into the foe''s side of the field.'),
    ('3.0', 'trace', 'Trace', 'This Pokemon mimics the special characteristics of the others, making them look as if they were its own.', 'This Pokemon copies the Ability of a random foe when it comes out. The effect ends if this Pokemon is removed from the battle. Unique Abilities can''t be copied.'),
    ('3.0', 'transistor', 'Transistor', 'This Pokemon''s body stores and boosts electric charges. It will constantly be releasing menacing lightning all over the place.', 'Add 2 Extra dice to the Damage Pool of all Physical or Special Electric-Type Moves that this Pokemon performs.'),
    ('3.0', 'triage', 'Triage', 'The Pokemon feels the urgency to treat the injured; it is also very quick to stitch and make knots. A skill often used to instantly mend wounds.', 'All Support Moves of this Pokemon with the effect of Basic Heal, Cure Status are considered to have: "Reaction 1" as Added Effect.'),
    ('3.0', 'truant', 'Truant', 'This Pokemon is extremely lazy. They won''t make even the tiniest effort to do anything even in the heat of battle.', 'Roll this Pokemon''s Loyalty every other turn, and score at least 2 successes. If the roll fails this Pokemon refuses to act. If it is successful it may act normally.'),
    ('3.0', 'turboblaze', 'Turboblaze', 'The Pokemon surrounds everything with a giant ball of swirling flames that prevents its foes from being out of reach, there is no escaping the heat.', 'If a Type, Move, Item or Ability would prevent this Pokemon from targeting a foe or inflicting an effect, ignore it. (e.g. A Pokemon with Immunity can be Poisoned, Ground-Type Pokemon can be hit with Electric Moves, etc.) Unique Ability.'),
    ('3.0', 'unaware', 'Unaware', 'The Pokemon is oblivious to many details in its surroundings, it will rarely take notice of things going on.', 'This Pokemon ignores any Increase or Reduction on the foe''s Attributes. This effect applies when dealing and receiving damage from a foe.'),
    ('3.0', 'unburden', 'Unburden', 'This Pokemon is most comfortable when it is freed from having to carry stuff around. It loves to be able to move without restrictions.', 'The first time this Pokemon spends or loses its held item and is no longer holding any, Increase 2 Points to its Dexterity Attribute.'),
    ('3.0', 'unnerve', 'Unnerve', 'It may be its powerful gaze or its menacing presence, but others near this Pokemon become really nervous to the point where they lose their appetite.', 'Foes cannot consume their held berry or recycled berries while this Pokemon is in the field.'),
    ('3.0', 'unseen-fist', 'Unseen Fist', 'This Pokemon moves and fights with amazing speed, you can''t really see their movements and your foe''s can''t either.', 'Shield Moves, Force Fields, Substitute decoys and cover are ignored by this Pokemon''s Non-Ranged Physical Moves. Unique Ability.'),
    ('3.0', 'vessel-of-ruin', 'Vessel of Ruin', 'There is a cursed artifact on this Pokemon. A dreadful tremor of fear invades everyone. This Pokemon loves to terrorize and frighten others.', 'Reduce by 2 the Special of everyone in the field, except this Pokemon. This Pokemon is immune to the effects of the Abilities: Beads of Ruin, Sword of Ruin, Tablets of Ruin, and Vessel of Ruin. Unique Ability.'),
    ('3.0', 'victory-star', 'Victory Star', 'This Pokemon''s presence is an incredible boost for morale. Those who get its favor will be guided to victory.', 'All Physical and Special Moves of the user and allies in range are considered to have: "Never Miss" as Added Effect. Unique Ability.'),
    ('3.0', 'vital-spirit', 'Vital Spirit', 'The Pokemon is incredibly active and energetic. It needs constant activity and exercise or else it will act destructive. It never sleeps.', 'This Pokemon is immune to the Sleep status. Moves or Items that self-inflict Sleep will fail.'),
    ('3.0', 'volt-absorb', 'Volt Absorb', 'This Pokemon''s body is practically a battery that is always happy to become charged to full capacity.', 'When this Pokemon is hit by an Electric-Type Move, you may restore 1 HP instead of receiving damage. Electric-Type Moves do not deal damage to this Pokemon.'),
    ('3.0', 'wandering-spirit', 'Wandering Spirit', 'The Pokemon is a wandering ghost with a haunted expression on its face. It won''t heed your call and might get lost floating aimlessly. Get to a medium to heal it.', 'If this Pokemon hits a foe with a Non-Ranged Physical Move, switch its Ability with the foe''s. Unique Abilities can''t be switched.'),
    ('3.0', 'water-absorb', 'Water Absorb', 'The Pokemon''s body is mostly made of water, it stores water inside itself and uses it for nourishment.', 'When this Pokemon is hit by a Water-Type Move, you may restore 1 HP instead of receiving damage. Water-Type Moves do not deal damage to this Pokemon.'),
    ('3.0', 'water-bubble', 'Water Bubble', 'The Pokemon is shielded by a water bubble. Strangely, the bubble is filled with clear water inside instead of air.', 'Reduce by 1 the total damage dealt to this Pokemon by Fire-Type Moves. 1st and 2nd Degree Burns deal no Damage to this Pokemon. Add 2 Extra Dice to the Damage Pool of this Pokemon''s Water-Type Moves.'),
    ('3.0', 'water-compaction', 'Water Compaction', 'The body of the Pokemon can absorb water at an astounding rate, its body hardens as it quickly dries.', 'The first time this Pokemon is hit by a Water-Type Move, Increase its Defense by 2. Water-type moves do not deal damage to this Pokemon.'),
    ('3.0', 'water-veil', 'Water Veil', 'This Pokemon is always wet and producing water to keep itself moist. Thanks to this, the Pokemon can stay away from a body of water for a long time.', 'The Pokemon is immune to all Burn degrees.'),
    ('3.0', 'weak-armor', 'Weak Armor', 'This Pokemon''s protective outer layers can come off, allowing it to move freely and be more agile.', 'The first time this Pokemon is hit by any Physical Move, Increase its Dexterity Attribute by 1 and Reduce its Defense by 1.'),
    ('3.0', 'well-baked-body', 'Well-Baked Body', 'This Pokemon''s body develops a thick bread-like crust when it is exposed to heat, filling the air with a buttery aroma.', 'The first time this Pokemon is hit by a Fire-Type Move, Increase its Defense by 2. Fire-type moves do not deal damage to this Pokemon.'),
    ('3.0', 'white-smoke', 'White Smoke', 'The Pokemon is constantly releasing fumes of white smoke making it difficult to be seen. It uses the smoke to conceal itself.', 'Other Pokemon cannot reduce the Attributes of this Pokemon. This Pokemon can still Reduce its own Attributes.'),
    ('3.0', 'wimp-out', 'Wimp Out', 'The Pokemon goes into a lot of stress whenever its exoskeleton is weakened, it can escape from any situation out of sheer cowardice.', 'Whenever this Pokemon reaches half or less of its total HP, it will switch out to its pokeball, sending an Ally to take its place. If there is no Ally, the battle may end. This Ability''s effect is not affected by Block.'),
    ('3.0', 'wind-power', 'Wind Power', 'This Pokemon uses wind currents to charge itself with electricity, tie a cable to its leg while it flies and get yourself an eco-friendly generator.', 'Whenever this Pokemon receives damage from a wind Move, Add 2 Extra Dice to the Damage pool of the next Electric-Type Move this Pokemon performs. This effect does not stack.'),
    ('3.0', 'wind-rider', 'Wind Rider', 'This Pokemon can soar no matter if there is a light breeze or a wind tempest raging, a true master of the sky.', 'Add 1 Extra Die to the Damage Pool of all Wind Moves.'),
    ('3.0', 'wonder-guard', 'Wonder Guard', 'This Pokemon''s body is protected by an incredible otherworldly aura. Most things get through as if nothing was there.', 'This Pokemon only receives damage from Status Ailments/Conditions, and Moves that deal Super Effective damage against it. This Pokemon is immune to damage from other sources like weather conditions and entry hazards. Unique Ability.'),
    ('3.0', 'wonder-skin', 'Wonder Skin', 'The skin of this Pokemon is covered by a thin protective veil that allows it to weaken dangerous hazards.', 'Reduce up to 2 Chance Dice from Effects of Moves or Abilities that target this Pokemon. (Example: The move Ember has 1 Chance Dice to Burn the foe, against this Pokemon it has zero Chance Dice).'),
    ('3.0', 'zen-mode', 'Zen Mode', 'Under extreme stress, this Pokemon will unlock its hidden psychic abilities through the power of meditation, it will go back to normal the next day.', 'Only Darmanitan may use this Ability. When at half or less of its HP, change to Zen Mode Form at the end of the Round. Use its Zen Mode Form from then on. Adjust its Attributes according to the Rank and Limits it has for each Form. Unique Ability.'),
    ('3.0', 'zero-to-hero', 'Zero to Hero', 'The Pokemon has a secret super-hero identity that even its trainer is unaware of as they conveniently retreat when the super-hero arrives.', 'Only Palafin may use this Ability. After switching out, change to Hero Form. Use its Hero Form when it switches back in. Adjust its Attributes according to the Rank and Limits it has for each Form. Unique Ability.');
insert into public.catalog_abilities (rules_version, id, name, description, effect)
